    /**
     * Tests getting all LegalHolds.
     *
     * @return    Collection
     */
    public List<LegalHold> testGetAll() throws Throwable {
    LOGGER.info( "LegalHoldTest:testGetAll() - Retrieving Collection of LegalHolds:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all LegalHold : " );
    List<LegalHold> collection  = null;

    try {
        // call the static get method on the LegalHoldService
        collection = service.getAllLegalHold();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            LegalHold currEntity  = null;
            Iterator<LegalHold> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getLegalHoldId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

